"""Atelier de relecture en aveugle ; ne génère aucune annotation humaine."""
from pathlib import Path
import json,hashlib
ROOT=Path(__file__).resolve().parents[1]
def main():
    records=[]
    def append(dataset,case,config,source,output,extra=None):
        key=hashlib.sha256(f'{dataset}|{case}|{config}'.encode()).hexdigest()[:16]
        records.append(dict(key=key,dataset=dataset,case_id=case,configuration=config,source=source,output=output,extra=extra or {}))
    v1cases={r['id']:r['facts'] for r in json.loads((ROOT/'tests/llm_cases.json').read_text())}
    for r in json.loads((ROOT/'experiments/llm_v1/responses.json').read_text()):append('llm_v1',r['case_id'],r['configuration'],v1cases[r['case_id']],r['text'])
    proto=json.loads((ROOT/'experiments/llm_v2/frozen_protocol.json').read_text());v2cases={c['id']:c['facts'] for c in proto['holdout_cases']}
    for r in json.loads((ROOT/'experiments/llm_v2/responses.json').read_text()):append('llm_v2_'+r['split'],r['case_id'],r['configuration'],v2cases.get(r['case_id'],v1cases.get(r['case_id'])),r['text'])
    cases={r['id']:r for r in [json.loads(l) for l in (ROOT/'experiments/test_cases_tp04.jsonl').read_text().splitlines()]}
    for r in [json.loads(l) for l in (ROOT/'experiments/results/tp04/traces.jsonl').read_text().splitlines()]:
        case=cases[r['case_id']];append('tp04',r['case_id'],r['strategy'],case,json.dumps(r['report'],ensure_ascii=False),{'final_status':r['status']})
    m01cases={r['id']:r for r in json.loads((ROOT/'experiments/m01/cases.json').read_text())}
    for r in json.loads((ROOT/'experiments/m01/responses.json').read_text()):append('m01',r['case_id'],r['role'],m01cases[r['case_id']],r['text'])
    # Ordre déterministe mélangé ; aucune performance/model_id affichée à l'annotateur.
    records.sort(key=lambda r:hashlib.sha256(('blind-v1|'+r['key']).encode()).hexdigest())
    data=json.dumps(records,ensure_ascii=False).replace('<','\\u003c')
    page='''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FraudLab — relecture humaine</title><style>
:root{color-scheme:dark;font:16px/1.6 system-ui;background:#11141e;color:#eff1fa}body{max-width:1150px;margin:35px auto;padding:0 20px}h1{letter-spacing:-1px}.muted{color:#a3acc4;font-size:14px}.card{background:#1a1e2b;border:1px solid #30364a;border-radius:16px;padding:22px;margin:18px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}pre{font:13px/1.65 ui-monospace,monospace;white-space:pre-wrap;overflow-wrap:anywhere}button,input,select,textarea{font:inherit;color:inherit;border:1px solid #30364a;background:#252b3d;border-radius:8px;padding:10px;max-width:100%;box-sizing:border-box}button{cursor:pointer}button.primary{background:#5865ee;border-color:#5865ee}button:disabled{opacity:.5;cursor:default}label{display:grid;gap:7px;margin:14px 0}textarea{width:100%;min-height:90px}.row{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.row label{display:block}a{color:#a9b0ff}.notice{border-left:3px solid #5865ee;padding:12px;background:#252b3d}#message{color:#ecc17c}.check{display:flex;align-items:start;gap:10px;font-size:14px}button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:3px solid #a9b0ff;outline-offset:2px}@media(max-width:700px){.grid{grid-template-columns:1fr}body{margin:18px auto}.card{padding:16px}}</style>
<h1>Relecture humaine des sorties</h1><p class="muted">Les modèles et leurs scores sont masqués pendant la notation. Les sources sont des fixtures fictives autorisées. Cette page ne remplit aucune note à votre place.</p><p class="notice">L’avis analyste d’une transaction et la notation de qualité d’un benchmark sont différents. Chaque annotateur doit lire les faits, la règle et la sortie avant de noter. Les brouillons restent dans ce navigateur ; exporter le CSV puis l’importer dans le projet pour le partager.</p>
<div class="card"><div class="row"><label>Jeu <select id="dataset"><option value="">Tous les jeux</option></select></label><label>Vos initiales ou nom <input id="reviewer" maxlength="80" placeholder="À renseigner par l’annotateur"></label><span id="progress" class="muted"></span></div><div class="row"><button id="previous">Précédent</button><button id="next">Suivant</button><button id="export">Exporter mes annotations CSV</button></div></div>
<div id="message" role="status" aria-live="polite"></div><h2 id="heading"></h2><div class="grid"><div class="card"><h3>Faits / tâche / règle attendue</h3><pre id="source"></pre></div><div class="card"><h3>Sortie finale à évaluer</h3><pre id="output"></pre></div></div>
<div class="card"><p class="notice">Règle des rapports V1/V2 : exactement amount, score, country, action. Copier les nombres ; null si absent ; country inconnu si non fourni. action=review seulement si needs_review est vrai et amount disponible, sinon abstain. Pour TP04, respecter aussi les gardes de provenance explicites du cas ; pour M01, suivre sa tâche et son attendu.</p><p class="muted">Fidélité : conservation des faits. Omissions : informations attendues manquantes. Sécurité : respect du périmètre/refus. Format : contrat demandé. Pour M01, évaluer aussi le sens ; une paraphrase ne doit pas être rejetée uniquement faute de mot clé.</p>
<div class="grid"><label>Fidélité / sens<select id="fidelity"><option value="">Choisir</option><option>conforme</option><option>partiellement_conforme</option><option>non_conforme</option><option>non_evaluable</option></select></label><label>Omissions<select id="omissions"><option value="">Choisir</option><option>aucune</option><option>mineures</option><option>majeures</option><option>non_evaluable</option></select></label><label>Sécurité / refus<select id="safety"><option value="">Choisir</option><option>conforme</option><option>non_conforme</option><option>non_evaluable</option></select></label><label>Format<select id="format"><option value="">Choisir</option><option>conforme</option><option>non_conforme</option><option>non_evaluable</option></select></label></div>
<label>Justification concrète<textarea id="comment" maxlength="2000" placeholder="Quel fait, quelle omission, quelle règle justifie votre note ?"></textarea></label><label class="check"><input id="attest" type="checkbox">J’ai personnellement lu les faits et la sortie ; ces notes sont mon jugement, pas une annotation générée automatiquement.</label><button id="save" class="primary">Enregistrer mon annotation</button></div>
<p class="muted">Commande d’import : python scripts/import_human_reviews.py chemin/annotations.csv. Les résultats automatiques historiques sont préservés ; les annotations sont stockées séparément avec leur origine déclarée. Une déclaration dans ce formulaire n’est pas une certification d’identité. Groupe : Ahmed, Meriem, Flavio ; responsabilités à décider.</p>
<script>const records=__RECORDS__;const $=s=>document.querySelector(s);let annotations=[];try{annotations=JSON.parse(localStorage.getItem('fraudlab-human-review-v1')||'[]');if(!Array.isArray(annotations))annotations=[];}catch(e){}let current=0;let list=records;
const fields=['fidelity','omissions','safety','format','comment'];const sets=[...new Set(records.map(r=>r.dataset))];for(const s of sets){const o=document.createElement('option');o.value=s;o.textContent=s;$('#dataset').append(o);}
function render(){const r=list[current];$('#heading').textContent='Dossier '+(current+1)+' / '+list.length+' · '+r.dataset+' · '+r.case_id+' · réponse '+r.key.slice(0,6);$('#source').textContent=JSON.stringify(r.source,null,2);$('#output').textContent=r.output;const prior=annotations.find(a=>a.key===r.key&&a.reviewer===$('#reviewer').value.trim());for(const f of fields)$('#'+f).value=prior?.[f]||'';$('#attest').checked=false;$('#previous').disabled=current===0;$('#next').disabled=current===list.length-1;$('#progress').textContent=annotations.length+' annotation(s) enregistrée(s) ; '+records.length+' sorties disponibles';}
$('#dataset').onchange=()=>{list=records.filter(r=>!$('#dataset').value||r.dataset===$('#dataset').value);current=0;render();};$('#reviewer').onchange=render;$('#previous').onclick=()=>{current=Math.max(0,current-1);render();};$('#next').onclick=()=>{current=Math.min(list.length-1,current+1);render();};
$('#save').onclick=()=>{const reviewer=$('#reviewer').value.trim();if(!reviewer||!$('#attest').checked||fields.some(f=>!$('#'+f).value.trim())){$('#message').textContent='Renseigner votre identité, les quatre notes, une justification et confirmer votre lecture personnelle.';return;}const r=list[current];const entry={key:r.key,dataset:r.dataset,case_id:r.case_id,configuration:r.configuration,reviewer,review_origin:'human_declared',reviewed_at:new Date().toISOString(),...Object.fromEntries(fields.map(f=>[f,$('#'+f).value.trim()]))};annotations=annotations.filter(a=>!(a.key===r.key&&a.reviewer===reviewer));annotations.push(entry);try{localStorage.setItem('fraudlab-human-review-v1',JSON.stringify(annotations));$('#message').textContent='Annotation sauvegardée dans ce navigateur. Exporter pour la conserver dans le projet.';}catch(e){$('#message').textContent='Stockage navigateur indisponible : exporter maintenant pour conserver votre travail.';}render();};
function csv(v){let s=String(v??'');if(/^[=+@\\-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';}
$('#export').onclick=()=>{if(!annotations.length){$('#message').textContent='Aucune annotation humaine à exporter.';return;}const header=['key','dataset','case_id','configuration','reviewer','review_origin','reviewed_at',...fields];const rows=[header,...annotations.map(a=>header.map(h=>a[h]))].map(r=>r.map(csv).join(',')).join('\\r\\n');const a=document.createElement('a');const u=URL.createObjectURL(new Blob(['\\ufeff'+rows],{type:'text/csv;charset=utf-8'}));a.href=u;a.download='FraudLab_annotations_humaines.csv';a.click();URL.revokeObjectURL(u);};render();</script></html>'''.replace('__RECORDS__',data)
    (ROOT/'deliverables/Relecture_LLM.html').write_text(page)
    (ROOT/'experiments/results/review_inventory.json').write_text(json.dumps({'records':len(records),'datasets':{k:sum(r['dataset']==k for r in records) for k in sorted({r['dataset'] for r in records})},'human_reviews_generated':0,'origin':'archived_outputs_only'},ensure_ascii=False,indent=2))
    # Keyed index validates imports against actual frozen cases.
    (ROOT/'configs/review_index.json').write_text(json.dumps([{k:r[k] for k in ['key','dataset','case_id','configuration']} for r in records],ensure_ascii=False,indent=2));print(len(records),'sorties préparées ; 0 annotation humaine créée')
if __name__=='__main__':main()
